import{_ as o,o as a,c as s,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Macro-Loops.md","filePath":"manual-en/Macro-Loops.md","lastUpdated":1785684581000}'),r={name:"manual-en/Macro-Loops.md"};function n(p,e,i,l,c,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h4 id="_14-2-9-macro-loops" tabindex="-1">14.2.9 Macro Loops <a class="header-anchor" href="#_14-2-9-macro-loops" aria-label="Permalink to &quot;14.2.9 Macro Loops&quot;">​</a></h4><p>The body of a macro may include two forms of loops: loops over numerical ranges and loops over tokens. Both forms expand a <em>loop body</em> multiple times, each time setting a named <em>loop variable</em> to a different value. The loop body typically expands the loop variable at least once.</p><p>The MITERATE setting (see <a href="./SET#SET-MITERATE">SET MITERATE</a>) limits the number of iterations in a loop. This is a safety measure to ensure that macro expansion terminates. PSPP issues a warning when the MITERATE limit is exceeded.</p><h4 id="loops-over-ranges" tabindex="-1">Loops Over Ranges <a class="header-anchor" href="#loops-over-ranges" aria-label="Permalink to &quot;Loops Over Ranges&quot;">​</a></h4><pre><code>!DO !var = start !TO end [!BY step]
  body
!DOEND
</code></pre><p>A loop over a numerical range has the form shown above. start, end, and step (if included) must be expressions with numeric values. The macro processor accepts both integers and real numbers. The macro processor expands body for each numeric value from start to end, inclusive.</p><p>The default value for step is 1. If step is positive and <em>first &gt; last</em>, or if step is negative and <em>first &lt; last</em>, then the macro processor doesn’t expand the body at all. step may not be zero.</p><h4 id="loops-over-tokens" tabindex="-1">Loops Over Tokens <a class="header-anchor" href="#loops-over-tokens" aria-label="Permalink to &quot;Loops Over Tokens&quot;">​</a></h4><pre><code>!DO !var !IN (expression)
  body
!DOEND
</code></pre><p>A loop over tokens takes the form shown above. The macro processor evaluates expression and expands body once per token in the result, substituting the token for !var each time it appears.</p>`,10)])])}const u=o(r,[["render",n]]);export{h as __pageData,u as default};
